import React from 'react';
import { useIntl } from 'react-intl';
import { Row } from 'react-table';
import styled from 'styled-components';

import Borders from '@dynatrace/strato-design-tokens/borders';
import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import { MinusIcon, PlusIcon } from '@dynatrace/strato-icons';

import { Button } from '../../../buttons/button/Button.js';
import type { DataTableSubRowsCellProps } from '../../types/shared-table-types.js';

// #region StyledComponents

interface SubRowsConnectorContainerProps {
  subRowsDepth: number;
}

const SubRowsConnectorContainer = styled(
  'div',
).attrs<SubRowsConnectorContainerProps>(({ subRowsDepth }) => ({
  style: {
    width: `calc(${Spacings.Size24} + calc(${Spacings.Size16} * ${subRowsDepth}))`,
  },
}))<SubRowsConnectorContainerProps>({
  position: 'relative',
  height: '100%',
});

interface SubRowsTriggerProps {
  left: number;
}

const SubRowsTrigger = /* @__PURE__ */ styled(
  Button,
).attrs<SubRowsTriggerProps>(({ left }) => ({
  style: { left },
}))<SubRowsTriggerProps>({
  borderRadius: Borders.Radius.Field.Subdued,
  padding: `0 ${Spacings.Size2}`,
  position: 'absolute',
  top: '50%',
  transform: 'translateY(-50%)',
});
interface SubRowsConnectorProps {
  left: number;
  right: number;
}

const SubRowsConnector = /* @__PURE__ */ styled(
  'svg',
).attrs<SubRowsConnectorProps>(({ left, right }) => ({
  style: { left, right },
}))<SubRowsConnectorProps>({
  position: 'absolute',
  top: 0,
  bottom: 0,
  '& path': {
    fill: 'none',
    stroke: Colors.Border.Neutral.Default,
    strokeWidth: 1,
  },
});
// #endregion StyledComponents

export const SubRowsCell = (props: DataTableSubRowsCellProps) => {
  const TRIGGER_WIDTH = 24;
  const CONNECTOR_ELEMENT_WIDTH = 16;
  const intl = useIntl();
  const {
    updateOpenSubRows,
    subRowsDepth,
    currentRowIndex,
    state: { pageIndex, pageSize },
  } = props;
  const row: Row = props.row;
  const rows: Row[] = props.rows;
  const pathHeight = 100;

  // paths for the respective connector elements
  const getTConnectorPath = (level: number) => {
    return `M${
      CONNECTOR_ELEMENT_WIDTH * level + CONNECTOR_ELEMENT_WIDTH / 2
    } 0 L${
      CONNECTOR_ELEMENT_WIDTH * level + CONNECTOR_ELEMENT_WIDTH / 2
    } ${pathHeight} M${
      CONNECTOR_ELEMENT_WIDTH * level + CONNECTOR_ELEMENT_WIDTH / 2
    } ${pathHeight / 2} L${
      CONNECTOR_ELEMENT_WIDTH * level + CONNECTOR_ELEMENT_WIDTH
    } ${pathHeight / 2} `;
  };
  const getLConnectorPath = (level: number) => {
    return `M${
      CONNECTOR_ELEMENT_WIDTH * level + CONNECTOR_ELEMENT_WIDTH / 2
    } 0 L${CONNECTOR_ELEMENT_WIDTH * level + CONNECTOR_ELEMENT_WIDTH / 2} ${
      pathHeight / 2
    } L${CONNECTOR_ELEMENT_WIDTH * level + CONNECTOR_ELEMENT_WIDTH} ${
      pathHeight / 2
    } `;
  };
  const getLineConnectorPath = (level: number) => {
    return `M${
      CONNECTOR_ELEMENT_WIDTH * level + CONNECTOR_ELEMENT_WIDTH / 2
    } 0 L${
      CONNECTOR_ELEMENT_WIDTH * level + CONNECTOR_ELEMENT_WIDTH / 2
    } ${pathHeight} `;
  };

  // connector before the trigger
  let connectorBeforePath = '';
  let connectorBeforeWidth = CONNECTOR_ELEMENT_WIDTH * row.depth;

  // figure out necessary connectors to the parent rows and following sub rows
  if (row.depth > 0) {
    const originalParentId = row.id.split('.')[0];
    const followingDepths: Record<number, boolean> = {};
    // if defined, consider pagination when calculating the next row's index for the rows array
    let nextRowIndex =
      pageSize === undefined
        ? currentRowIndex + 1
        : pageSize * pageIndex + currentRowIndex + 1;

    while (
      rows[nextRowIndex] &&
      rows[nextRowIndex].id.startsWith(originalParentId)
    ) {
      const rowDepth = rows[nextRowIndex].depth;
      if (!followingDepths[rowDepth]) {
        followingDepths[rowDepth] = true;
      }
      nextRowIndex++;
    }

    // for each depth level before the current one, check which connector elements need to be rendered
    Array.from(Array(row.depth).keys()).forEach((depth) => {
      if (depth < row.depth - 1) {
        connectorBeforePath += followingDepths[depth + 1]
          ? getLineConnectorPath(depth)
          : '';
      } else {
        connectorBeforePath += followingDepths[depth + 1]
          ? getTConnectorPath(depth)
          : getLConnectorPath(depth);
      }
    });
  }

  // connector after the trigger
  const isTopLevelRowWithoutSubRows = row.depth === 0 && !row.hasSubRows;
  const isSubRowWithoutSubRows = row.depth > 0 && !row.hasSubRows;
  const depthDifference = isTopLevelRowWithoutSubRows
    ? 0
    : subRowsDepth - row.depth;
  const connectorAfterOffset = connectorBeforeWidth + TRIGGER_WIDTH;
  const connectorAfterWidth = CONNECTOR_ELEMENT_WIDTH * depthDifference;

  if (isSubRowWithoutSubRows) {
    // extend the before connector instead of rendering a trigger
    connectorBeforePath += `M${CONNECTOR_ELEMENT_WIDTH * row.depth + 0} ${
      pathHeight / 2
    } L${CONNECTOR_ELEMENT_WIDTH * row.depth + TRIGGER_WIDTH} ${
      pathHeight / 2
    } `;
    connectorBeforeWidth += TRIGGER_WIDTH;
  }

  return (
    <SubRowsConnectorContainer subRowsDepth={subRowsDepth}>
      {connectorBeforeWidth > 0 && (
        <SubRowsConnector
          height="100%"
          width={connectorBeforeWidth}
          viewBox={`0 0 ${connectorBeforeWidth} 100`}
          preserveAspectRatio="none"
          right={connectorBeforeWidth}
          left={0}
        >
          <path d={connectorBeforePath} vectorEffect="non-scaling-stroke" />
        </SubRowsConnector>
      )}
      {row.hasSubRows && (
        <SubRowsTrigger
          aria-label={
            row.subRowsOpen
              ? intl.formatMessage({
                  defaultMessage: 'Close sub row',
                  id: '4PAGimamOnP3FmhS',
                  description:
                    "Aria label used for the table's sub row close trigger.",
                })
              : intl.formatMessage({
                  defaultMessage: 'Open sub row',
                  id: '1ZsgHaQCQ0217VTL',
                  description:
                    "Aria label used for the table's sub row open trigger.",
                })
          }
          variant="default"
          aria-controls={row.ariaControls}
          disabled={row.subRowsDisabled}
          onClick={() => updateOpenSubRows(row.id)}
          left={connectorBeforeWidth}
        >
          <Button.Prefix>
            {row.subRowsOpen ? <MinusIcon /> : <PlusIcon />}
          </Button.Prefix>
        </SubRowsTrigger>
      )}
      {depthDifference > 0 && (
        <SubRowsConnector
          width={connectorAfterWidth}
          height="100%"
          viewBox={`0 0 ${connectorAfterWidth} 100`}
          preserveAspectRatio="none"
          left={connectorAfterOffset}
          right={connectorAfterOffset + connectorAfterWidth}
        >
          <path
            d={`M0 ${pathHeight / 2} L${connectorAfterWidth} ${pathHeight / 2}`}
            vectorEffect="non-scaling-stroke"
          />
        </SubRowsConnector>
      )}
    </SubRowsConnectorContainer>
  );
};
